import {createHash} from 'node:crypto';import {mockAtlas,atlasBeaches,atlasCatalog,atlasContours} from './nextjs-atlas.mjs';
export async function mockMapNavigationRaces(page,base){await mockAtlas(page,base);const beaches=structuredClone(atlasBeaches);beaches.beaches[1].detail_file='data/portsea-slow.json';const secondContours={...atlasContours,features:atlasContours.features.map(f=>({...f,properties:{...f.properties,depth_m:f.properties.depth_m+20}}))};const bodies={'beaches.json':beaches,'data/catalog.json':atlasCatalog,'data/portsea-slow.json':{beaches:[beaches.beaches[1]],stays:[],surveys:[]},'data/example-bay-contours.json':atlasContours,'data/second-bay-contours.json':secondContours,'guides.json':{},'social.json':{posts:[]},'data/beach-summaries.json':{beaches:[]}},files=Object.fromEntries(Object.entries(bodies).map(([path,data])=>{const body=JSON.stringify(data);return [path,{hash:createHash('sha256').update(body).digest('hex'),bytes:Buffer.byteLength(body),label:path}];}));for(const [path,json]of Object.entries(bodies))await page.route('**/'+path+'*',r=>r.fulfill({json}));await page.route('**/data/downloads.json*',r=>r.fulfill({json:{version:1,revision:'races',files,regions:{}}}));return bodies;}
